        // Act
        executeUpdate()
        // Assert
        verify(configuration).size = SIZE_MIN
    }

    @Test
    fun updateSetsMaximumSizeWhenPackageNameIsUnavailable() {
        // Arrange
        whenever(INSTANCE.mainActivity.packageName).thenThrow(IllegalStateException())
        // Act
        executeUpdate()
        // Assert
        verify(configuration).size = SIZE_MAX
    }

    @Test
    fun onGroupCollapsed() {
        // Arrange
