        assertThat(fixture.parent(-1)).isEqualTo(WiFiDetail.EMPTY)
        assertThat(fixture.child(0, 0)).isEqualTo(WiFiDetail.EMPTY)
        assertThat(fixture.child(0, -1)).isEqualTo(WiFiDetail.EMPTY)
    }

